package app

import (
	"errors"
	"fmt"
)

// ErrNotFound is the sentinel returned (wrapped) when an id is missing.
var ErrNotFound = errors.New("not found")

func lookup(id int) error {
	if id <= 0 {
		return fmt.Errorf("lookup id=%d: %w", id, ErrNotFound)
	}
	return nil
}

// IsMissing reports whether looking up id produced a not-found error.
// BUG: it compares with == against ErrNotFound, but lookup wraps the sentinel
// with %w, so the wrapped error is not == ErrNotFound and this returns false
// even for a genuine miss. Should use errors.Is.
func IsMissing(id int) bool {
	err := lookup(id)
	return err == ErrNotFound
}

