package app

import "testing"

func TestIsMissingTrueForWrappedSentinel(t *testing.T) {
	if !IsMissing(0) {
		t.Fatal("expected IsMissing(0) to be true (wrapped ErrNotFound)")
	}
	if !IsMissing(-5) {
		t.Fatal("expected IsMissing(-5) to be true")
	}
}

func TestIsMissingFalseWhenPresent(t *testing.T) {
	if IsMissing(7) {
		t.Fatal("expected IsMissing(7) to be false (no error)")
	}
}

